//! Split-KV decode chunking config: the chunk-size formula and the
//! `split_kv_{chunk}x{max}` label/parse round-trip for the manifest variant sweep.

use serde::Deserialize;
use serde::Serialize;

/// One split-KV decode configuration: a per-chunk token floor and a per-request chunk cap.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct SplitKvConfig {
    pub chunk_tokens: usize,
    pub max_chunks_per_request: usize,
}

impl SplitKvConfig {
    pub const fn new(chunk_tokens: usize, max_chunks_per_request: usize) -> Self {
        // A zero `max_chunks_per_request` divides by zero in `actual_chunk_size` (and a zero
        // `chunk_tokens` does in `active_chunks` at kv_len==0); reject loud at construction
        // (compile-time for the const sites) rather than panic mid-decode.
        assert!(
            chunk_tokens != 0 && max_chunks_per_request != 0,
            "SplitKvConfig requires non-zero chunk_tokens and max_chunks_per_request"
        );
        Self {
            chunk_tokens,
            max_chunks_per_request,
        }
    }

    /// Chunk size for a `kv_len`-token request: the floor, coarsened to keep the
    /// request within `max_chunks_per_request` chunks.
    pub fn actual_chunk_size(self, kv_len: usize) -> usize {
        self.chunk_tokens
            .max(kv_len.div_ceil(self.max_chunks_per_request))
    }

    pub fn active_chunks(self, kv_len: usize) -> usize {
        kv_len.div_ceil(self.actual_chunk_size(kv_len)).max(1)
    }

    /// The `split_kv_{chunk}x{max}` manifest variant name.
    pub fn label(self) -> String {
        format!(
            "split_kv_{}x{}",
            self.chunk_tokens, self.max_chunks_per_request
        )
    }

    /// Inverse of [`label`](Self::label): parse `split_kv_{chunk}x{max}` back into a config.
    /// `None` on a malformed label or a zero field.
    pub fn parse(label: &str) -> Option<Self> {
        let (chunk, max_chunks) = label.strip_prefix("split_kv_")?.split_once('x')?;
        let chunk_tokens: usize = chunk.parse().ok()?;
        let max_chunks_per_request: usize = max_chunks.parse().ok()?;
        if chunk_tokens == 0 || max_chunks_per_request == 0 {
            return None;
        }
        Some(Self::new(chunk_tokens, max_chunks_per_request))
    }
}

#[cfg(test)]
mod tests {
    use super::SplitKvConfig;

    #[test]
    fn label_parse_round_trips() {
        for cfg in [
            SplitKvConfig::new(64, 64),
            SplitKvConfig::new(64, 256),
            SplitKvConfig::new(256, 64),
            SplitKvConfig::new(512, 64),
        ] {
            assert_eq!(SplitKvConfig::parse(&cfg.label()), Some(cfg));
        }
    }

    #[test]
    fn parse_rejects_malformed() {
        assert_eq!(SplitKvConfig::parse("non_partition"), None);
        assert_eq!(SplitKvConfig::parse("split_kv_64"), None);
        assert_eq!(SplitKvConfig::parse("split_kv_axb"), None);
        assert_eq!(SplitKvConfig::parse("split_kv_64x0"), None);
        assert_eq!(SplitKvConfig::parse("split_kv_0x64"), None);
    }
}

use pegainfer_kernels::ops::NumericPolicy;

use crate::DecodeOverlap;
use crate::config::TensorParallelConfig;

/// The production path for Qwen3 decode projections.
///
/// Only QKV is fused. Gate/up remains on the established split-GEMM path until
/// its component and end-to-end evidence independently qualifies it.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum DecodeProjectionPath {
    Split,
    FusedQkv,
}

impl DecodeProjectionPath {
    pub(crate) const fn fuses_qkv(self) -> bool {
        matches!(self, Self::FusedQkv)
    }
}

/// Current-head production qualifications. A row is
/// `(SM, hidden_size, q_dim, kv_dim, num_hidden_layers)`.
///
/// Keep this table deliberately narrow: cuBLASLt selects an algorithm inside
/// one GEMM shape, but does not decide whether the packed topology beats three
/// split GEMMs. Every added row therefore requires component and end-to-end A/B
/// evidence for that exact device architecture and model geometry.
const QUALIFIED_QKV: &[(i32, usize, usize, usize, usize)] =
    &[(89, 2560, 4096, 1024, 36), (89, 4096, 4096, 1024, 36)];

pub(crate) fn select_decode_projection_path(
    tensor_parallel: TensorParallelConfig,
    numeric_policy: NumericPolicy,
    decode_overlap: DecodeOverlap,
    draft_enabled: bool,
    device_sm: i32,
    hidden_size: usize,
    q_dim: usize,
    kv_dim: usize,
    num_hidden_layers: usize,
) -> (DecodeProjectionPath, &'static str) {
    if tensor_parallel.world_size != 1 {
        return (DecodeProjectionPath::Split, "tensor_parallel");
    }
    if numeric_policy != NumericPolicy::Tuned {
        return (DecodeProjectionPath::Split, "numeric_policy");
    }
    if !matches!(decode_overlap, DecodeOverlap::Off) {
        return (DecodeProjectionPath::Split, "decode_overlap");
    }
    if draft_enabled {
        return (DecodeProjectionPath::Split, "speculative");
    }
    if !QUALIFIED_QKV.contains(&(device_sm, hidden_size, q_dim, kv_dim, num_hidden_layers)) {
        return (DecodeProjectionPath::Split, "unqualified_sm_or_geometry");
    }
    (DecodeProjectionPath::FusedQkv, "qualified_sm_and_geometry")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn enables_qualified_qwen3_tp1_decode() {
        let (path, reason) = select_decode_projection_path(
            TensorParallelConfig::default(),
            NumericPolicy::Tuned,
            DecodeOverlap::Off,
            false,
            89,
            2560,
            4096,
            1024,
            36,
        );
        assert_eq!(path, DecodeProjectionPath::FusedQkv);
        assert!(path.fuses_qkv());
        assert_eq!(reason, "qualified_sm_and_geometry");
    }

    #[test]
    fn fails_closed_outside_qualified_runtime_environment() {
        let cases = [
            select_decode_projection_path(
                TensorParallelConfig {
                    rank: 0,
                    world_size: 2,
                },
                NumericPolicy::Tuned,
                DecodeOverlap::Off,
                false,
                89,
                2560,
                4096,
                1024,
                36,
            ),
            select_decode_projection_path(
                TensorParallelConfig::default(),
                NumericPolicy::Pin,
                DecodeOverlap::Off,
                false,
                89,
                2560,
                4096,
                1024,
                36,
            ),
            select_decode_projection_path(
                TensorParallelConfig::default(),
                NumericPolicy::PerToken,
                DecodeOverlap::Off,
                false,
                89,
                2560,
                4096,
                1024,
                36,
            ),
            select_decode_projection_path(
                TensorParallelConfig::default(),
                NumericPolicy::Tuned,
                DecodeOverlap::SharedSm,
                false,
                89,
                2560,
                4096,
                1024,
                36,
            ),
            select_decode_projection_path(
                TensorParallelConfig::default(),
                NumericPolicy::Tuned,
                DecodeOverlap::GreenCtx { decode_pct: 20 },
                false,
                89,
                2560,
                4096,
                1024,
                36,
            ),
            select_decode_projection_path(
                TensorParallelConfig::default(),
                NumericPolicy::Tuned,
                DecodeOverlap::Off,
                true,
                89,
                2560,
                4096,
                1024,
                36,
            ),
            select_decode_projection_path(
                TensorParallelConfig::default(),
                NumericPolicy::Tuned,
                DecodeOverlap::Off,
                false,
                86,
                2560,
                4096,
                1024,
                36,
            ),
            select_decode_projection_path(
                TensorParallelConfig::default(),
                NumericPolicy::Tuned,
                DecodeOverlap::Off,
                false,
                89,
                3072,
                4096,
                1024,
                36,
            ),
        ];

        assert!(
            cases
                .into_iter()
                .all(|(path, _)| path == DecodeProjectionPath::Split && !path.fuses_qkv())
        );
    }
}

