401	    }
402	
403	    /// Reads back `synced_split_kv`.
404	    #[cfg(feature = "kernel-call-trace")]
405	    pub(crate) fn resolved_split_kv(&self) -> (usize, usize) {
406	        self.synced_split_kv
407	            .expect("resolved_split_kv read off a SplitKv step / before sync_split_kv_meta")
408	    }
409	
410	    fn sync_split_kv_meta(
411	        &mut self,
412	        ctx: &DeviceContext,
413	        kv_views: &[&KvView],
414	        padded_bs: usize,
415	    ) -> Result<()> {
416	        // Clear before the NonPartition early return so trace cannot reuse stale SplitKv metadata.
417	        #[cfg(feature = "kernel-call-trace")]
418	        {
419	            self.synced_split_kv = None;
420	        }
421	        // Tuned skips split metadata past the cap (NonPartition); Pin/PerToken build the CSR for
422	        // every bucket. The construction snapshot here and the live-policy `split_chunk_size`/
423	        // `max_split_chunks` below are held equal by the `batch_decode` entry assert, so the CSR fits.
424	        if padded_bs > SPLIT_KV_MAX_BATCH_SIZE
425	            && matches!(self.policy_at_construction, NumericPolicy::Tuned)
426	        {
427	            return Ok(());
428	        }
429	        let split_chunk_size = self.split_chunk_size();
430	        let cap = max_split_chunks();
431	        #[cfg(feature = "kernel-call-trace")]
432	        {
433	            self.synced_split_kv = Some((split_chunk_size, cap));
434	        }
435	        let kv_lens: Vec<usize> = kv_views.iter().map(|kv| kv.seq_len()).collect();
436	        let csr = build_split_kv_csr(split_chunk_size, cap, &kv_lens, padded_bs)?;
437	
438	        let split_kv_chunk_size = [split_chunk_size as i32];
439	        ctx.stream
440	            .memcpy_htod(&csr.request_indices, &mut self.split_request_indices_d)?;
441	        ctx.stream
442	            .memcpy_htod(&csr.kv_tile_indices, &mut self.split_kv_tile_indices_d)?;
443	        ctx.stream
444	            .memcpy_htod(&split_kv_chunk_size, &mut self.split_kv_chunk_size_d)?;
445	        ctx.stream
446	            .memcpy_htod(&csr.o_indptr, &mut self.split_o_indptr_d)?;
447	        ctx.stream
448	            .memcpy_htod(&csr.block_valid_mask, &mut self.split_block_valid_mask_d)?;
449	        self.split_padded_slots = padded_bs * cap;
450	
451	        Ok(())
452	    }
453	
454	    /// Decode attention kernel. Tuned selects on batch (SplitKv fills the SMs below the cap,
455	    /// NonPartition above). Pin/PerToken pin SplitKv for every bucket so it never varies with
456	    /// co-batched load — the chunk count is already request-local (`pin_chunk_size`).
457	    pub(crate) fn attention_path(padded_bs: usize, policy: NumericPolicy) -> DecodeAttentionPath {
458	        if matches!(policy, NumericPolicy::Pin | NumericPolicy::PerToken) {
459	            return DecodeAttentionPath::SplitKv;
460	        }
461	        if padded_bs <= SPLIT_KV_MAX_BATCH_SIZE {
462	            DecodeAttentionPath::SplitKv
463	        } else {
464	            DecodeAttentionPath::NonPartition
465	        }
466	    }
467	
468	    pub(crate) fn graph_index(bucket_idx: usize, path: DecodeAttentionPath) -> usize {
469	        bucket_idx * DECODE_ATTENTION_PATH_COUNT + path.graph_slot()
470	    }
471	}
